import{_ as a,C as i,o as n,c,ap as t,j as o,a as d,E as r}from"./chunks/framework.D5dqwIER.js";const C=JSON.parse('{"title":"Coordinate systems (numerical)","description":"","frontmatter":{},"headers":[],"relativePath":"api/coorsystems_num.md","filePath":"api/coorsystems_num.md","lastUpdated":null}'),l={name:"api/coorsystems_num.md"},m={class:"jldocstring custom-block",open:""};function p(f,e,u,y,h,_){const s=i("Badge");return n(),c("div",null,[e[3]||(e[3]=t('<h1 id="api-coorsystems-num" tabindex="-1">Coordinate systems (numerical) <a class="header-anchor" href="#api-coorsystems-num" aria-label="Permalink to &quot;Coordinate systems (numerical) {#api-coorsystems-num}&quot;">​</a></h1><p>The same operators with derivatives by automatic differentiation. Usage: <a href="/TensND.jl/dev/manual/coorsystems_num#man-coorsystems-num">Numerical coordinate systems</a>.</p><p>The accessors listed under <a href="./coorsystems">Coordinate systems</a> — <code>lame_coefficients</code>, <code>christoffel</code>, <code>normalized_basis</code>, <code>natural_basis</code>, <code>unitvec</code>, <code>natvec</code> — all take an extra point argument here.</p>',3)),o("details",m,[o("summary",null,[e[0]||(e[0]=o("a",{id:"TensND.PointwiseGeometry",href:"#TensND.PointwiseGeometry"},[o("span",{class:"jlbinding"},"TensND.PointwiseGeometry")],-1)),e[1]||(e[1]=d()),r(s,{type:"info",class:"jlObjectType jlType",text:"Type"})]),e[2]||(e[2]=t('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PointwiseGeometry{X,R,G} </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> AbstractGeometry</span></span></code></pre></div><p>The geometry of a chart as three functions of the point <code>x</code> (an <code>AbstractVector</code> of coordinates), for differential operators by automatic differentiation:</p><ul><li><p><code>χ_func(x)</code> : the Lamé coefficients at <code>x</code>;</p></li><li><p><code>R_func(x)</code> : the rotation matrix whose columns are the unit vectors of the normalized basis at <code>x</code>, in Cartesian components;</p></li><li><p><code>Γ_func(x)</code> : the Christoffel symbols at <code>x</code>, <code>Γ[i,j,k] = Γᵏᵢⱼ</code>.</p></li></ul><p>A <a href="/TensND.jl/dev/api/coorsystems#TensND.CoordinateSystem"><code>CoordinateSystem</code></a> of this geometry takes fields as functions of the point and returns functions of the point: <code>grad(f, CS)</code> is <code>x₀ -&gt; ∇f(x₀)</code>. The bases and the Lamé coefficients depend on the point too, and are read with it: <code>normalized_basis(CS, x₀)</code>, <code>lame_coefficients(CS, x₀)</code>, ….</p><p>Predefined: <code>coorsys_cartesian(PointwiseGeometry)</code>, <code>coorsys_polar(PointwiseGeometry)</code>, <code>coorsys_cylindrical(PointwiseGeometry)</code>, <code>coorsys_spherical(PointwiseGeometry)</code>, each with an optional element type (<code>Float64</code> by default); any chart from its position vector with <code>CoordinateSystem(OM_func, dim, T)</code>.</p>',5))])])}const b=a(l,[["render",p]]);export{C as __pageData,b as default};
